const incoming = $input.first().json;
const isTestWebhook = incoming.body !== undefined && incoming.query !== undefined;
if (isTestWebhook) {
  const expectedSecret = $vars.AGF_LINKEDIN_WEBHOOK_SECRET;
  const receivedSecret = incoming.headers?.['x-agf-webhook-secret'] || incoming.headers?.['X-AGF-Webhook-Secret'];
  if (!expectedSecret || receivedSecret !== expectedSecret) throw new Error('Webhook de teste do LinkedIn não autorizado.');
}
const message = isTestWebhook ? incoming.body : incoming;
const readHeader = (name) => {
  const direct = message.headers?.[name.toLowerCase()] ?? message.headers?.[name];
  if (typeof direct === 'string') return direct;
  const list = Array.isArray(message.payload?.headers) ? message.payload.headers : [];
  return list.find((item) => String(item.name).toLowerCase() === name.toLowerCase())?.value ?? '';
};
const messageId = message.id ?? message.message_id ?? '';
if (!messageId) throw new Error('Mensagem do Gmail sem identificador.');
const from = message.from ?? readHeader('From');
const address = (from.match(/<([^>]+)>/)?.[1] ?? from).trim().toLowerCase();
// So o remetente oficial de convites conta. Newsletter e resumo semanal do
// LinkedIn tambem citam nomes e nao podem mover card nenhum.
if (address !== 'invitations@linkedin.com') return [];
const subject = message.subject ?? readHeader('Subject');
if (!/accepted your invitation|aceitou seu convite|aceitou o seu convite/i.test(subject)) return [];
// O assunto traz so o primeiro nome; o nome completo esta no display do
// remetente, no formato "Fulano de Tal via LinkedIn".
const fullName = from
  .replace(/<[^>]*>/, '')
  .replace(/^[\s"']+|[\s"']+$/g, '')
  .replace(/\s+via\s+LinkedIn\s*$/i, '')
  .trim();
if (!fullName) throw new Error('E-mail de aceite sem nome no remetente.');
const html = String(message.html ?? message.textHtml ?? '');
const plain = String(message.text ?? message.textPlain ?? '');
const body = (plain || html
  .replace(/<br\s*\/?\s*>/gi, '\n')
  .replace(/<\/(?:p|div|li|tr|td|h\d)>/gi, '\n')
  .replace(/<[^>]+>/g, ''))
  .replace(/&amp;/gi, '&')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&#39;/gi, "'")
  .replace(/&quot;/gi, '"')
  .replace(/\r/g, '');
const lines = body.split('\n').map((line) => line.trim()).filter(Boolean);
// O cargo e sempre a linha logo abaixo da repeticao do nome completo. E dele
// que sai a empresa usada para desempatar homonimos no Supabase.
const nameIndex = lines.findIndex((line) => line.toLowerCase() === fullName.toLowerCase());
const candidate = nameIndex >= 0 ? (lines[nameIndex + 1] ?? '') : '';
const headline = /^(message|mensagem|ver perfil|view profile|https?:)/i.test(candidate) || candidate.length > 200
  ? ''
  : candidate;
const receivedAt = message.internalDate
  ? new Date(Number(message.internalDate)).toISOString()
  : (readHeader('Date') ? new Date(readHeader('Date')).toISOString() : new Date().toISOString());
return [{
  json: {
    payload: {
      message_id: messageId,
      full_name: fullName,
      headline,
      received_at: receivedAt,
    },
  },
}];
